//! dsh whole-list todos, session-owned and cleared at the start of each user turn.
use serde_json::{json,Value};
#[derive(Default)]pub struct TodoSession{state:Option<Value>}
impl TodoSession{pub fn view(&self)->Value{self.state.clone().unwrap_or(Value::Null)}pub fn reset(&mut self){self.state=None;}pub fn write(&mut self,args:&Value)->Result<Value,String>{let obj=args.as_object().ok_or("arguments must be object")?;if obj.len()!=1||!obj.contains_key("todos"){return Err("todos required; no other arguments allowed".into())}let raw=args["todos"].as_array().ok_or("todos must be array")?;let mut seen=std::collections::BTreeSet::new();let mut todos=vec![];let(mut pending,mut active,mut completed)=(0,0,0);for item in raw{let o=item.as_object().ok_or("todo must be object")?;if o.len()!=2||!o.contains_key("content")||!o.contains_key("status"){return Err("todo requires only content and status".into())}let content=item["content"].as_str().ok_or("content must be string")?.trim();if content.is_empty(){return Err("content must be non-empty string".into())}if !seen.insert(content){return Err("duplicate todo content".into())}let status=item["status"].as_str().ok_or("status must be string")?;match status{"pending"=>pending+=1,"in_progress"=>active+=1,"completed"=>completed+=1,_=>return Err("invalid todo status".into())}todos.push(json!({"content":content,"status":status}));}let out=json!({"todos":todos,"counts":{"pending":pending,"inProgress":active,"completed":completed}});self.state=Some(out["todos"].clone());Ok(out)}}
pub fn render(v:&Value)->String{format!("Updated todo list: {} pending, {} in progress, {} completed.",v["counts"]["pending"],v["counts"]["inProgress"],v["counts"]["completed"])}

pub fn card_text(todos:&Value)->String{todos.as_array().map(|list|list.iter().map(|t|format!("[{}] {}",t["status"].as_str().unwrap_or(""),t["content"].as_str().unwrap_or(""))).collect::<Vec<_>>().join("\n")).unwrap_or_default()}
